// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EsaSite) predicate.EsaSite {
	return predicate.EsaSite(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EsaSite) predicate.EsaSite {
	return predicate.EsaSite(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EsaSite) predicate.EsaSite {
	return predicate.EsaSite(sql.NotPredicates(p))
}
